    core = [row[1:-1] for row in grid[1:-1]]
    h, w = len(core), len(core[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if core[r][c] == 8 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and core[ny][nx] != 8 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            y0, y1 = min(y for y, x in cells), max(y for y, x in cells)
            x0, x1 = min(x for y, x in cells), max(x for y, x in cells)
            block = [row[x0:x1 + 1] for row in core[y0:y1 + 1]]
            if h < w:
                block = [list(row) for row in zip(*block)][::-1]
            components.append((x0, y0, block))
    if h < w:
        if grid[-1][0] == 2:
            components.sort(key=lambda item: -item[1])
        else:
            components.sort(key=lambda item: item[1])
    else:
        components.sort(key=lambda item: (item[0], item[1]))
    width = max(len(block[0]) for _, _, block in components)
    output = []
    for _, _, block in components:
        pad = (width - len(block[0])) // 2
        for row in block:
            output.append([8] * pad + row + [8] * (width - pad - len(row)))
    return output
